    variable: ts.Identifier | null;
    awaitExpr: ts.AwaitExpression;
    postAwaitStatements: readonly ts.Statement[];
    returnExpr: ts.Expression | null;
    params: AsyncAwaitContinuationParam[];
    thisValue: EmitResult | null;
