            stageBuf.close();
            stageBuf.open("else");
            stageBuf.line("tsc_try_pop();");
            stageBuf.line("tsc_promise_reject_in_place(_ret, tsc_value_string(tsc_current_error()));");
            stageBuf.close();
            stageBuf.close();
