        buf.open(`if (tsc_promise_is_pending(${sourceVar}))`);
        buf.line(`tsc_promise_add_callback(${sourceVar}, ${initialAdapter}, ${envVar});`);
        buf.close();
        buf.open("else");
        buf.line(`${initialAdapter}(${envVar});`);
        buf.close();
        buf.line(`return ${resultVar};`);
